import { NAV_CELL_M } from '@shared/constants';
import { z } from 'zod';
import {
  REQUIRED_ANCHOR_IDS,
  REQUIRED_ZONE_IDS,
  SNAKE_ID_PATTERN,
  ZONE_KINDS,
} from '../levelNodeNames.ts';

// `content/levels/<id>.geometry.json` is generated by `npm run assets:extract` from the `.glb`
// the Blender export writes: never edit it by hand. Every coordinate is a glTF coordinate in
// metres (x right, y up, z toward the viewer). Same rules as the other schemas: strict, camelCase,
// units in the names, no default.

const idSchema = (description: string) =>
  z.string().regex(SNAKE_ID_PATTERN, 'an id is lower_snake_case').describe(description);

const vec3M = (description: string) =>
  z.tuple([z.number(), z.number(), z.number()]).describe(description);

const boxFields = {
  centerM: vec3M('Centre of the box, in metres.'),
  halfExtentsM: z
    .tuple([z.number().min(0), z.number().min(0), z.number().min(0)])
    .describe('Half the size of the box along x, y and z, in metres.'),
};

const ColliderSchema = z
  .strictObject({
    id: idSchema('Name of the `COL_<id>` node.'),
    ...boxFields,
  })
  .describe('A static collider box (axis-aligned).');

const AnchorSchema = z
  .strictObject({
    id: idSchema('Name of the `ANCHOR_<id>` node.'),
    positionM: vec3M('World position of the anchor, in metres.'),
  })
  .describe('A named point the level and the threats refer to.');

const ZoneSchema = z
  .strictObject({
    id: idSchema('Name after `ZONE_<kind>_`.'),
    kind: z.enum(ZONE_KINDS).describe('What the zone means to the game.'),
    ...boxFields,
  })
  .describe('A gameplay volume (axis-aligned).');

const PropSchema = z
  .strictObject({
    id: idSchema('`<kind>_<nn>` of the `PROP_<kind>_<nn>` node.'),
    kind: idSchema('The kind of prop (`mug` for `PROP_mug_01`).'),
    ...boxFields,
  })
  .describe('A dynamic prop at its start position.');

const NavSchema = z
  .strictObject({
    originM: z
      .tuple([z.number(), z.number()])
      .describe('x and z of the corner of cell (0, 0), in metres.'),
    cols: z.int().positive().describe('Number of columns (cells along x).'),
    rowCount: z.int().positive().describe('Number of rows (cells along z); equals `rows.length`.'),
    rows: z
      .array(z.string().regex(/^[01]+$/, 'a row is made of 0 and 1 only'))
      .describe(
        'One string per row of z: `1` walkable, `0` blocked. Column `c` covers x = originM[0] + c * cellM.',
      ),
  })
  .describe('The walkable grid.');

function duplicates(ids: readonly string[]): string[] {
  const seen = new Set<string>();
  const dup = new Set<string>();
  for (const id of ids) (seen.has(id) ? dup : seen).add(id);
  return [...dup];
}

export const LevelGeometrySchema = z
  .strictObject({
    id: idSchema('The level id; equals the file name before `.geometry.json`.'),
    cellM: z
      .literal(NAV_CELL_M, {
        error: `cellM must be ${NAV_CELL_M} (NAV_CELL_M): the sim's grid maths assume it`,
      })
      .describe('Side of one navigation cell, in metres; always `NAV_CELL_M`.'),
    boundsMinM: vec3M('Lowest corner of the box that holds every visual node, in metres.'),
    boundsMaxM: vec3M('Highest corner of the box that holds every visual node, in metres.'),
    colliders: z.array(ColliderSchema),
    nav: NavSchema,
    anchors: z.array(AnchorSchema),
    zones: z.array(ZoneSchema),
    props: z.array(PropSchema),
  })
  .check((context) => {
    const level = context.value;
    const fail = (path: (string | number)[], message: string): void => {
      context.issues.push({ code: 'custom', input: level, path, message });
    };

    for (const [list, items] of [
      ['colliders', level.colliders],
      ['anchors', level.anchors],
      ['zones', level.zones],
      ['props', level.props],
    ] as const) {
      for (const id of duplicates(items.map((item) => item.id))) {
        fail([list], `duplicate id "${id}"`);
      }
    }

    level.nav.rows.forEach((row, index) => {
      if (row.length !== level.nav.cols) {
        fail(
          ['nav', 'rows', index],
          `a row has ${row.length} cells, \`cols\` says ${level.nav.cols}`,
        );
      }
    });
    if (level.nav.rows.length !== level.nav.rowCount) {
      fail(
        ['nav', 'rowCount'],
        `\`rowCount\` is ${level.nav.rowCount} but there are ${level.nav.rows.length} rows`,
      );
    }

    for (const axis of [0, 1, 2] as const) {
      if ((level.boundsMinM[axis] as number) >= (level.boundsMaxM[axis] as number)) {
        fail(['boundsMaxM', axis], 'the upper bound must be above the lower bound');
      }
    }

    for (const required of REQUIRED_ANCHOR_IDS) {
      if (!level.anchors.some((anchor) => anchor.id === required)) {
        fail(['anchors'], `missing the required anchor "${required}"`);
      }
    }
    for (const required of REQUIRED_ZONE_IDS) {
      const zone = level.zones.find((candidate) => candidate.id === required);
      if (zone === undefined) {
        fail(['zones'], `missing the required zone "${required}"`);
      } else if (zone.kind !== 'hidden') {
        fail(
          ['zones'],
          `the required zone "${required}" must be of kind "hidden" (it is "${zone.kind}")`,
        );
      }
    }

    level.anchors.forEach((anchor, index) => {
      const outside = ([0, 1, 2] as const).some((axis) => {
        const value = anchor.positionM[axis] as number;
        return (
          value < (level.boundsMinM[axis] as number) || value > (level.boundsMaxM[axis] as number)
        );
      });
      if (outside)
        fail(['anchors', index, 'positionM'], `anchor "${anchor.id}" is outside \`bounds\``);
    });
  })
  .describe(
    'Geometry of one level, generated from its `.glb` (colliders, navigation grid, anchors, zones, props).',
  );

export type LevelGeometry = z.infer<typeof LevelGeometrySchema>;
